const CASE_COUNT = (() => { let fs = []; try { fs = readdirSync(join(root, "site", "cases")).filter((f) => f.endsWith(".html")).map((f) => f.slice(0, -5)); } catch {} return new Set([...Object.keys(DATA.CASES || {}), ...Object.keys(DATA.CANVASES || {}), ...fs, "steam"]).size; })();
